"""Read-only multi-server audit inventory, exact previews and session boundaries."""
import json,time
from desktop_fixture import Peer,Desktop,expect,ROOT

out=ROOT/'artifacts/audit-storage-ui'/str(time.time_ns());checks=[]
def passed(text):checks.append(text);print(text,flush=True)
def rows():
    result=[dict(id=f'audit-{n:04}',modified=1700000000+n) for n in range(105)]
    result[102]['reasons']=['residuals'];result[101]['reasons']=['referenced'];result[100].update(service='active',reasons=['active'])
    return result

with Peer(out/'peer-a') as a,Peer(out/'peer-b') as b:
    export=dict(id='export-copy',modified=1700000000,action='export',source='audit-0101',reasons=['export_data','referenced'],logical_bytes=300,allocated_bytes=16384)
    for peer in [a,b]:(peer.root/'audit-storage-fixture.json').write_text(json.dumps(dict(cleanup=rows(),recovery=[export])))
    config=a.config([a.profile('Alpha'),b.profile('Beta')],out);host,port=b.data['address'].rsplit(':',1)
    config['config']['trusted_hosts'].append(dict(host=host,port=int(port),fingerprint=b.data['host_key_rsa_fingerprint']))
    with Desktop(out/'desktop',config) as app:
        p=app.page;p.locator('.rail-tasks').click();p.get_by_role('button',name='Cleanup reports',exact=True).click()
        d=p.get_by_role('dialog',name='Connect to cleanup reports',exact=True)
        expect(d.locator('.cleanup-report-target')).to_have_count(2)
        for button in d.locator('.cleanup-report-target').all():button.click()
        d.get_by_role('button',name='Read cleanup reports',exact=True).click();expect(d).not_to_be_visible()
        expect(p.locator('.cleanup-query-state')).to_have_text(['Cleanup report query completed']*2)
        p.get_by_role('button',name='Audit and export storage…',exact=True).click()
        expect(p.locator('.audit-storage-state')).to_have_text(['Audit storage query completed']*2)
        expect(p.locator('.audit-storage-record')).to_have_count(200)
        a_group=p.locator('.audit-storage-group').first
        expect(a_group.locator('.audit-storage-summary')).to_contain_text('105 Audit records')
        p.get_by_role('textbox',name='Minimum audit age (days)',exact=True).fill('0')
        p.get_by_role('textbox',name='Keep latest audit records',exact=True).fill('1')
        for identifier in ['audit-0104','audit-0103','audit-0102','audit-0101','audit-0100']:
            a_group.get_by_role('button',name=identifier,exact=True).click()
        a_group.get_by_role('button',name='Next audit page',exact=True).click();expect(a_group.locator('.audit-storage-record')).to_have_count(5)
        a_group.get_by_role('button',name='audit-0000',exact=True).click()
        expect(a_group.locator('.audit-storage-selected')).to_have_text('Selected audit records: 6 / 100')
        a_group.get_by_role('button',name='Preview selected audit records',exact=True).click()
        expect(a_group.locator('.audit-preview-summary')).to_contain_text('Retention candidates: 2')
        details=a_group.locator('.audit-preview-objects')
        for text in ['audit-0000/request.json','audit-0103/runner.py','Among the latest retained audit records','Source quarantine still exists','Referenced by another audit record','Server task is still active']:
            expect(details).to_contain_text(text)
        details.scroll_into_view_if_needed();app.screenshot('retention-preview.png');passed('Two unselected servers expose private storage, bounded pages and exact cross-page previews with retention and evidence protections')
        old=details.inner_text();(a.root/'audit-storage-denied').touch()
        a_group.get_by_role('button',name='Preview selected audit records',exact=True).click()
        expect(a_group.locator('.audit-storage-state')).to_have_text('Report query failed; previous snapshots are retained')
        expect(details).to_have_text(old);(a.root/'audit-storage-denied').unlink()
        for flag in ['audit-storage-wrong-scope','audit-storage-wrong-selection']:
            (a.root/flag).touch();a_group.get_by_role('button',name='Preview selected audit records',exact=True).click()
            expect(a_group.locator('.audit-storage-state')).to_have_text('Report query failed; previous snapshots are retained');expect(details).to_have_text(old);(a.root/flag).unlink()
        passed('Failed reads and mismatched roots or selections preserve the original snapshot instead of replacing it with unbound data')
        (a.root/'audit-storage-incomplete').touch();a_group.get_by_role('button',name='Preview selected audit records',exact=True).click()
        expect(a_group.locator('.audit-preview-summary')).to_contain_text('Retention candidates: 0');expect(details).to_contain_text('Audit references could not be fully inspected');(a.root/'audit-storage-incomplete').unlink()
        p.get_by_role('textbox',name='Keep latest audit records',exact=True).fill('0');a_group.get_by_role('button',name='Refresh audit storage',exact=True).click()
        expect(p.locator('.audit-storage-page>.form-error')).to_contain_text('1–1000');p.get_by_role('textbox',name='Keep latest audit records',exact=True).fill('1')
        passed('Incomplete references protect every selected record; invalid retention values fail before a remote query')
        (a.root/'audit-storage-slow').touch();a_group.get_by_role('button',name='Preview selected audit records',exact=True).click()
        expect(a_group.locator('.audit-storage-state')).to_have_text('Reading audit storage…')
        p.get_by_role('textbox',name='Keep latest audit records',exact=True).fill('2');time.sleep(2.4)
        expect(a_group.locator('.audit-storage-preview')).to_have_count(0)
        (a.root/'audit-storage-slow').unlink();p.get_by_role('textbox',name='Keep latest audit records',exact=True).fill('1')
        passed('Editing retention policy discards an in-flight preview for the old policy')
        p.get_by_role('button',name='Residual export storage',exact=True).click();expect(p.locator('.audit-storage-record')).to_have_count(2)
        a_group.get_by_role('button',name='export-copy',exact=True).click();a_group.get_by_role('button',name='Preview selected audit records',exact=True).click()
        expect(a_group.locator('.audit-preview-summary')).to_contain_text('Retention candidates: 0');expect(details).to_contain_text('Exported copies remain protected')
        p.get_by_role('button',name='Forget report credentials',exact=True).click();expect(p.locator('.audit-storage-record')).to_have_count(0);expect(p.locator('.audit-storage-preview')).to_have_count(0)
        expect(a_group.get_by_role('button',name='Refresh audit storage',exact=True)).to_be_disabled()
        p.get_by_role('button',name='Connect to cleanup reports…',exact=True).click();d=p.get_by_role('dialog',name='Connect to cleanup reports',exact=True)
        d.get_by_role('button',name='Read cleanup reports',exact=True).click();expect(p.locator('.audit-storage-record')).to_have_count(2)
        passed('Export bytes remain protected, forgetting clears private storage details, and reconnecting reads the current storage view')
        (a.root/'audit-storage-slow').touch();a_group.get_by_role('button',name='Refresh audit storage',exact=True).click()
        p.locator('.rail-scripts').click();time.sleep(2.4);p.locator('.rail-tasks').click()
        expect(p.locator('.audit-storage-record')).to_have_count(0);expect(a_group.get_by_role('button',name='Refresh audit storage',exact=True)).to_be_disabled()
        (a.root/'audit-storage-slow').unlink()
        app.settings('General');p.locator('.setting-language:visible').get_by_role('radio', name='简体中文', exact=True).check();expect(p.locator('.page-header-title')).to_have_text('常规');p.locator('.rail-tasks').click();p.set_viewport_size(dict(width=900,height=700))
        expect(p.get_by_role('button',name='残留导出存储',exact=True)).to_be_visible();assert p.evaluate('document.documentElement.scrollWidth<=innerWidth')
        p.get_by_role('button',name='连接清理报告…',exact=True).click();d=p.get_by_role('dialog',name='连接清理报告',exact=True)
        d.get_by_role('button',name='读取清理报告',exact=True).click();expect(p.locator('.audit-storage-record')).to_have_count(2)
        expect(a_group.locator('.audit-storage-summary')).to_contain_text('实际占用')
        expect(a_group.locator('.audit-storage-summary')).to_contain_text('逻辑大小')
        a_group.get_by_role('button',name='export-copy',exact=True).click();a_group.get_by_role('button',name='预览所选审计记录',exact=True).click()
        expect(a_group.locator('.audit-preview-summary')).to_contain_text('保留候选：0')
        expect(a_group.locator('.audit-preview-objects')).to_contain_text('导出副本保持保护')
        assert p.locator('.main-panel').evaluate('el=>el.scrollWidth<=el.clientWidth')
        assert not p.locator('.audit-storage-page').evaluate('root=>[...root.querySelectorAll("*")].filter(el=>!el.children.length&&el.textContent.trim()&&el.getClientRects().length&&getComputedStyle(el).visibility!=="hidden"&&parseFloat(getComputedStyle(el).fontSize)<12).length')
        a_group.locator('.audit-storage-preview').scroll_into_view_if_needed()
        app.screenshot('audit-storage-chinese-narrow.png')
        assert not app.config.with_suffix('.tasks.json').exists()
        saved=app.config.read_text();assert all(value not in saved for value in ['audit-0104','export-copy','fixture-admin-secret'])
        p.get_by_role('button',name='返回清理报告',exact=True).click();expect(p.locator('.audit-storage-page')).to_have_count(0)
        passed('Leaving Tasks rejects late private results; Chinese narrow layout is usable and no query creates task history or saves audit contents')

(out/'results.json').write_text(json.dumps(dict(passed=len(checks),checks=checks),ensure_ascii=False,indent=2),encoding='utf-8')
print(json.dumps(dict(passed=len(checks),artifacts=str(out)),ensure_ascii=False),flush=True)
